package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.SerializerProvider;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase._asTimestamp
 */
public class DateTimeSerializerBase__asTimestamp_TriageGen0Test {

    /**
     * Concrete implementation of the abstract class for testing purposes.
     */
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
            // Not needed for this test
        }

        @Override
        protected long _timestamp(Date value) {
            return value == null ? 0L : value.getTime();
        }

        @Override
        public com.fasterxml.jackson.databind.JsonSerializer<?> createContextual(SerializerProvider serializers, com.fasterxml.jackson.databind.ser.BeanProperty property) {
            return this;
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) {
            // Not needed
        }

        @Override
        protected void _acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint, boolean asNumber) {
            // Not needed
        }
    }

    @Test
    public void testAsTimestamp_UseTimestampIsNotNull_True() {
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, true, null);
        // Should return true immediately because _useTimestamp is not null
        assertTrue(_asTimestamp_Wrapper(serializer, null));
    }

    @Test
    public void testAsTimestamp_UseTimestampIsNotNull_False() {
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, false, null);
        // Should return false immediately because _useTimestamp is not null
        assertFalse(_asTimestamp_Wrapper(serializer, null));
    }

    @Test
    public void testAsTimestamp_UseTimestampIsNull_CustomFormatIsNull_FeatureEnabled() {
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        SerializerProvider sp = mock(SerializerProvider.class);
        when(sp.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(true);

        assertTrue(_asTimestamp_Wrapper(serializer, sp));
        verify(sp).isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    }

    @Test
    public void testAsTimestamp_UseTimestampIsNull_CustomFormatIsNull_FeatureDisabled() {
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        SerializerProvider sp = mock(SerializerProvider.class);
        when(sp.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(false);

        assertFalse(_asTimestamp_Wrapper(serializer, sp));
        verify(sp).isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAsTimestamp_UseTimestampIsNull_CustomFormatIsNull_NullProviderThrows() {
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        // Should throw IllegalArgumentException because serializers is null and customFormat is null
        _asTimestamp_Wrapper(serializer, null);
    }

    @Test
    public void testAsTimestamp_UseTimestampIsNull_CustomFormatIsNotNull() {
        DateFormat mockFormat = mock(DateFormat.class);
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, mockFormat);
        SerializerProvider sp = mock(SerializerProvider.class);

        // When customFormat is not null, it should return false regardless of provider
        assertFalse(_asTimestamp_Wrapper(serializer, sp));
        // Ensure provider was never queried
        verify(sp, never()).isEnabled(any());
    }

    /**
     * Helper to access the protected method.
     */
    private boolean _asTimestamp_Wrapper(TestDateTimeSerializer serializer, SerializerProvider serializers) {
        return serializer._asTimestamp(serializers);
    }
}
